import json

facts = [
 {
  "id": "laughter-climax-50-minutes",
  "source": "We noticed something special about 50 minutes into the show.",
  "claim": "The \u201cI don\u2019t wanna work anymore\u201d punchline is delivered at 0:50:11 (3011 seconds, 50.2 minutes) and draws 9.5 seconds of laughter.",
  "tables": {"c": "data/ali-wong--captions.csv"},
  "code": "c[c.caption.str.contains(\"I don't wanna work anymore\", regex=False)].assign(minutes=lambda d: d.timeStart/60).tail(1)[['start','timeStart','minutes','laugh']]"
 },
 {
  "id": "climax-conception-topic",
  "source": "The laughter climax is about conception.",
  "claim": "The climax falls in the 789-conception topic, which runs from 2990 to 3014 seconds.",
  "tables": {"t": "data/ali-wong--topics.csv"},
  "code": "t[t.group=='789-conception'][['group','timeStart','topicEnd']]"
 },
 {
  "id": "conception-preceded-by-hippies-orgasm",
  "source": "The punchline about conception was preceded by a reference to being a hippy, which was preceded by a description of a man\u2019s face during orgasm.",
  "claim": "The 789-conception topic starts at 2990 seconds, after the 787-hippies topic at 2983 seconds, which starts after the 782-orgasm topic at 2956 seconds.",
  "tables": {"t": "data/ali-wong--topics.csv"},
  "code": "t[t.group.isin(['789-conception','787-hippies','782-orgasm'])][['index','group','timeStart','topicEnd']]"
 },
 {
  "id": "hpv-three-parts",
  "source": "She has a whole digression about HPV that\u2019s divided into three parts: everyone has it, men don\u2019t get it, and Ali\u2019s experience at the doctor.",
  "claim": "The HPV digression is annotated as three topics, 32-hpv, 39-men and hpv, and 43-doctor and hpv, spanning 154 to 230 seconds.",
  "tables": {"t": "data/ali-wong--topics.csv"},
  "code": "t[t.group.str.contains('hpv')].assign(n=lambda d: len(d))[['index','level','group','timeStart','topicEnd','n']]"
 },
 {
  "id": "hpv-reached-through-sleep",
  "source": "But the reason she got to the topic of HPV was because of her difficulty falling asleep.",
  "claim": "The 32-hpv topic (154-230 seconds) is nested inside the 23-sleep topic (114-230 seconds): both end at 230 seconds and HPV begins at 154 seconds.",
  "tables": {"t": "data/ali-wong--topics.csv"},
  "code": "t[t.group.isin(['23-sleep','32-hpv'])][['group','timeStart','topicEnd']]"
 },
 {
  "id": "sleep-under-jealousy",
  "source": "And the reason she is talking about falling asleep: she\u2019s jealous of other women who can fall asleep, as well as their metabolism and inner thigh clearance.",
  "claim": "The 23-sleep topic (114-230 seconds) sits under 10-jealousy (62-230 seconds), alongside 16-metabolism (85-96 seconds) and 19-inner thigh clearance (96-111 seconds).",
  "tables": {"t": "data/ali-wong--topics.csv"},
  "code": "t[t.group.isin(['10-jealousy','16-metabolism','19-inner thigh clearance','23-sleep'])][['level','group','timeStart','topicEnd']]"
 },
 {
  "id": "three-main-themes",
  "source": "But if you take a step back, Ali\u2019s routine is structured around three cohesive ideas: getting older, marriage, and pregnancy.",
  "claim": "The three longest top-level topics are marriage (1840 seconds, 415-2255 seconds), pregnancy (1160 seconds, 2277-3437 seconds), and getting older (361 seconds, 49-410 seconds).",
  "tables": {"t": "data/ali-wong--topics.csv"},
  "code": "t[t.level==1].groupby('group').agg(start=('timeStart','min'), end=('topicEnd','max')).assign(seconds=lambda d: d.end-d.start).sort_values('seconds',ascending=False)"
 },
 {
  "id": "making-babies-three-minutes",
  "source": "We can tie this punchline to a larger three-minute story about making babies.",
  "claim": "The 747-making babies topic runs from 2846 to 3014 seconds, 168 seconds or 2.8 minutes.",
  "tables": {"t": "data/ali-wong--topics.csv"},
  "code": "t[t.group=='747-making babies'][['group','timeStart','topicEnd']].assign(seconds=lambda d: d.topicEnd-d.timeStart, minutes=lambda d: (d.topicEnd-d.timeStart)/60)"
 },
 {
  "id": "climax-repeats-working-line",
  "source": "The laughter climax connects the major themes of her routine, from how she met her husband to her philosophy on working.",
  "claim": "The phrase \u201cI don\u2019t wanna work anymore\u201d recurs at 0:21:14 and 0:21:31 in the 302-dependent topic, at 0:29:04 in the 446-diet topic, and at 0:50:11 in the 789-conception topic.",
  "tables": {"c": "data/ali-wong--captions.csv"},
  "code": "c[c.caption.str.contains(\"I don't wanna work anymore\", regex=False)][['start','timeStart','group']]"
 },
 {
  "id": "harvard-links-husband-and-working",
  "source": "The laughter climax connects the major themes of her routine, from how she met her husband to her philosophy on working.",
  "claim": "The word \u201cHarvard\u201d appears in the 111-met husband topic at 487 seconds, in the 302-dependent topic at 1271 seconds, and in the 789-conception topic at 3006 seconds.",
  "tables": {"c": "data/ali-wong--captions.csv"},
  "code": "c[c.caption.str.contains('Harvard', case=False, na=False)][['start','timeStart','group']]"
 }
]

skipped = [
 {
  "source": "In fact, this moment had the most laughter in the entire show. We\u2019ll call it the \u201claughter climax.\u201d",
  "why": "The captions file\u2019s longest single laugh is 10.0 seconds at 0:11:48, while the 0:50:11 punchline draws 9.5 seconds; by every laugh sum or smoothed window I computed, the peak falls near 11:45 rather than at 50 minutes, so this finding does not reproduce."
 },
 {
  "source": "She\u2019s telling not just 100 individual jokes, but a story that is deliberately arranged, much like a comedy film or a TV series.",
  "why": "The only countable unit in the data is 120 distinct topic labels; counting topic categories describes the data and does not measure \u201cjokes\u201d or reproduce the comparison with 100 jokes."
 },
 {
  "source": "It also \u201ccalls back\u201d to three other topics from earlier in the routine.",
  "why": "The topic table has only three callback annotations, but they sit at 2983, 3057, and 3408 seconds; only the first precedes the 50:11 climax, so the data does not mark three callbacks from the climax to earlier topics."
 },
 {
  "source": "Ali Wong\u2019s stand-up is closer to the right of this spectrum, relying less on one-liners and more on form-driven humor.",
  "why": "This is a comparison with other comedy forms (one-liners, films, TV shows), and the supplied files contain only Ali Wong\u2019s special, so the comparison cannot be computed."
 },
 {
  "source": "For 50 minutes, Ali has built a universe, with each joke expanding the audience\u2019s understanding of her world-view.",
  "why": "The 50-minute timing of the punchline is reproduced, but the claim about what the audience understands is interpretive rather than a value in the files."
 }
]

with open('facts.json','w') as f: json.dump(facts,f,ensure_ascii=False,indent=2)
with open('skipped.json','w') as f: json.dump(skipped,f,ensure_ascii=False,indent=2)
print('wrote', len(facts), len(skipped))
PYEOF
python3 /tmp/make_facts.py; ls -la facts.json skipped.json

